"""Unit tests for the ``.pre-commit-config.yaml`` writer and merge (``precommit.py``)."""

from __future__ import annotations

from typing import TYPE_CHECKING

import pytest
import yaml

from coding_agent_playbook.precommit import (
    DEFAULT_STAGES_NOTE,
    LEGACY_HOOK_WARNING,
    merge_pre_commit,
    write_pre_commit,
)

if TYPE_CHECKING:
    from pathlib import Path

# The pre-v0.16 ``playbook init`` starter (abridged to the playbook + mypy hooks).
LEGACY_STARTER = """\
# AUTOGENERATED starter by coding-agent-playbook `playbook init`.
default_language_version:
  python: python3.12
fail_fast: false
repos:
  - repo: local
    hooks:
      # The playbook — sync drift check
      - id: coding-agent-playbook-sync
        name: coding-agent-playbook sync
        entry: playbook sync --check
        language: system
        pass_filenames: false
        always_run: true
      - id: mypy
        name: mypy
        entry: mypy --config-file=pyproject.toml
        language: system
        pass_filenames: false
        always_run: true
"""
# What pre-v0.16 ``init`` appended to a consumer-curated config.
LEGACY_APPENDED = """\
repos:
  - repo: local
    hooks:
      - id: mine
        name: mine
        entry: echo hi
        language: system
  - repo: local
    hooks:
      - id: coding-agent-playbook-sync
        name: coding-agent-playbook sync
        entry: playbook sync --check
        language: system
        pass_filenames: false
        always_run: true
"""


def _hooks(content: str) -> dict[str, dict[str, object]]:
    data = yaml.safe_load(content)
    return {hook["id"]: hook for repo in data["repos"] for hook in repo["hooks"]}


def test_legacy_starter_hook_is_swapped_for_the_local_pair() -> None:
    merged = merge_pre_commit(LEGACY_STARTER, output_commit=False)
    hooks = _hooks(merged.content)
    assert "coding-agent-playbook-sync" not in hooks
    assert "sync drift check" not in merged.content
    assert hooks["coding-agent-playbook-autosync"]["stages"] == ["post-checkout", "post-merge"]
    assert hooks["coding-agent-playbook-no-generated-output"]["stages"] == ["pre-commit"]
    assert "mypy" in hooks
    assert merged.messages == (DEFAULT_STAGES_NOTE,)  # mypy would run on checkout


def test_legacy_appended_block_is_swapped_in_place() -> None:
    merged = merge_pre_commit(LEGACY_APPENDED, output_commit=False)
    hooks = _hooks(merged.content)
    assert set(hooks) == {
        "mine",
        "coding-agent-playbook-autosync",
        "coding-agent-playbook-no-generated-output",
    }
    assert merged.content.count("- repo: local") == 2


def test_swap_is_idempotent() -> None:
    once = merge_pre_commit(LEGACY_STARTER, output_commit=False).content
    assert merge_pre_commit(once, output_commit=False).content == once


def test_hand_edited_legacy_hook_is_kept_with_a_warning() -> None:
    edited = LEGACY_APPENDED.replace("always_run: true", "always_run: true\n        verbose: true")
    merged = merge_pre_commit("default_stages: [pre-commit]\n" + edited, output_commit=False)
    hooks = _hooks(merged.content)
    assert "coding-agent-playbook-sync" in hooks
    assert "coding-agent-playbook-no-generated-output" in hooks
    assert merged.messages == (LEGACY_HOOK_WARNING,)


def test_legacy_hook_with_a_changed_value_is_kept_with_a_warning() -> None:
    edited = LEGACY_APPENDED.replace(
        "language: system\n        pass", "language: python\n        pass"
    )
    merged = merge_pre_commit(edited, output_commit=False)
    assert "coding-agent-playbook-sync" in _hooks(merged.content)
    assert LEGACY_HOOK_WARNING in merged.messages


def test_legacy_hook_next_to_new_guard_is_only_warned_about() -> None:
    both = merge_pre_commit(
        LEGACY_APPENDED, output_commit=False
    ).content + LEGACY_APPENDED.removeprefix("repos:\n")
    merged = merge_pre_commit("default_stages: [pre-commit]\n" + both, output_commit=False)
    assert LEGACY_HOOK_WARNING in merged.messages


def test_fresh_curated_config_gets_pair_appended_and_stages_note() -> None:
    merged = merge_pre_commit("repos:", output_commit=False)
    assert merged.content.startswith("repos:\n  - repo: local\n")
    assert set(_hooks(merged.content)) == {
        "coding-agent-playbook-autosync",
        "coding-agent-playbook-no-generated-output",
    }
    assert "playbook sync --check-staged" in merged.content
    assert merged.messages == (DEFAULT_STAGES_NOTE,)


def test_no_note_when_default_stages_is_set() -> None:
    merged = merge_pre_commit("default_stages: [pre-commit]\nrepos:\n", output_commit=False)
    assert merged.messages == ()


def test_commit_true_appends_legacy_hook_once_without_messages() -> None:
    merged = merge_pre_commit("repos:\n", output_commit=True)
    assert _hooks(merged.content)["coding-agent-playbook-sync"]["entry"] == "playbook sync --check"
    assert merged.messages == ()
    again = merge_pre_commit(merged.content, output_commit=True)
    assert again.content == merged.content


@pytest.mark.parametrize("enabled", [False, True])
def test_write_pre_commit_starter_follows_the_booleans_it_is_given(
    tmp_path: Path, enabled: bool
) -> None:
    """init passes the template switches; precommit.py reads no config itself (CP-D4)."""
    path, messages = write_pre_commit(tmp_path, commit_trailers=enabled, commitizen=enabled)

    assert path == tmp_path / ".pre-commit-config.yaml"
    assert messages == ()
    hooks = _hooks(path.read_text(encoding="utf-8"))
    assert ("coding-agent-playbook-commit-trailers" in hooks) is enabled
    assert ("coding-agent-playbook-commit-msg" in hooks) is enabled


def test_write_pre_commit_merges_an_existing_config_and_returns_its_messages(
    tmp_path: Path,
) -> None:
    target = tmp_path / ".pre-commit-config.yaml"
    target.write_text(LEGACY_APPENDED, encoding="utf-8")

    path, messages = write_pre_commit(tmp_path, commit_trailers=True, commitizen=True)

    hooks = _hooks(path.read_text(encoding="utf-8"))
    assert set(hooks) == {
        "mine",
        "coding-agent-playbook-autosync",
        "coding-agent-playbook-no-generated-output",
    }
    assert messages == (DEFAULT_STAGES_NOTE,)
